import { useState } from "react";

function OrderList({ fetchOrders }) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [page, setPage] = useState(1);

  async function load(nextPage) {
    setLoading(true);
    setPage(nextPage);
    try {
      const orders = await fetchOrders(nextPage);
      setData(orders);
      setLoading(false);
    } catch (e) {
      setError(e.message);
      setLoading(false);
    }
  }

  // BUG: does not clear the previous error, so the spinner and the old
  // error render together on every retry.
  function retry() {
    setLoading(true);
    load(page);
  }

  if (loading) return <Spinner />;
  if (error) return <Error message={error} onRetry={retry} />;
  return <List items={data} onPage={load} />;
}

solution.reference:
import { useReducer } from "react";

const initialState = { status: "idle", data: null, error: null, page: 1 };

// Pure, testable without rendering anything.
function reducer(state, action) {
  switch (action.type) {
    case "fetch":
      // Clearing the error here is the fix: no call site can forget it.
      return { ...state, status: "loading", error: null, page: action.page };
    case "success":
      return { ...state, status: "success", data: action.data };
    case "failure":
      return { ...state, status: "error", error: action.error };
    default:
      throw new Error(`unknown action: ${action.type}`);
  }
}

function OrderList({ fetchOrders }) {
  const [state, dispatch] = useReducer(reducer, initialState);

  async function load(nextPage) {
    dispatch({ type: "fetch", page: nextPage });
    try {
      dispatch({ type: "success", data: await fetchOrders(nextPage) });
    } catch (e) {
      dispatch({ type: "failure", error: e.message });
    }
  }

  if (state.status === "loading") return <Spinner />;
  if (state.status === "error")
    return <Error message={state.error} onRetry={() => load(state.page)} />;
  return <List items={state.data} onPage={load} />;
}

// A single status field also makes "loading and error at once" unrepresentable,
// and dispatch has a stable identity, so passing it to memoized children never
// invalidates their memoization the way a fresh useCallback would.

