solution.reference:
function App() {
  const user = useCurrentUser();
  // The Avatar element is created HERE, where `user` already exists, and
  // travels down as an ordinary `children` prop.
  return (
    <Page>
      <Sidebar>
        <Nav>
          <Avatar user={user} />
        </Nav>
      </Sidebar>
    </Page>
  );
}

function Page({ children }) {
  return (
    <div className="page">
      <aside>{children}</aside>
      <Main />
    </div>
  );
}

function Sidebar({ children }) {
  return <aside>{children}</aside>;
}

function Nav({ children }) {
  return <nav>{children}</nav>;
}

function Avatar({ user }) {
  return <img src={user.avatarUrl} alt={user.name} />;
}

// Why composition rather than a UserContext:
//
// `children` is an ordinary prop. The element objects are created by App, so
// when Page, Sidebar or Nav re-render for their own reasons, the `children`
// they received is the SAME element reference as before and React can bail out
// of re-rendering that subtree. Memoization works because the value arrives
// through props.
//
// A context update does not arrive through props at all — it notifies every
// consumer directly, skipping the props diff, so React.memo on the intermediate
// components would not stop the propagation. Context earns its cost when the
// tree is genuinely deep AND the value changes rarely (theme, locale, session).
// Here it is three levels and the drilling disappears for free.

